package cl.bancoxyz.atmbff;import jakarta.servlet.http.HttpServletRequest;import org.springframework.cloud.client.loadbalancer.LoadBalanced;import org.springframework.context.annotation.*;import org.springframework.web.client.RestClient;import org.springframework.web.context.request.*;@Configuration public class RestClientConfig{@Bean @LoadBalanced RestClient.Builder client(){return RestClient.builder().requestInterceptor((req,body,exec)->{RequestAttributes a=RequestContextHolder.getRequestAttributes();if(a instanceof ServletRequestAttributes s){String h=s.getRequest().getHeader("Authorization");if(h!=null&&!h.isBlank())req.getHeaders().set("Authorization",h);}return exec.execute(req,body);});}}